using System;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.AspNetCore.Server.Kestrel.Core;
using Microsoft.Extensions.DependencyInjection;

namespace QuickCode.QuickCode.Portal.Helpers.BlobStorage;

public static class BlobImageStorageServiceCollectionExtensions
{
    /// <summary>
    /// Registers <see cref="IBlobImageStorage"/> based on BLOB_PROVIDER (azure | r2 | minio | s3 | local).
    /// Defaults to azure when unset. Also raises multipart/request body limits to the video max (20 MB).
    /// </summary>
    public static IServiceCollection AddBlobImageStorage(this IServiceCollection services)
    {
        services.Configure<FormOptions>(options =>
        {
            options.MultipartBodyLengthLimit = BlobUploadLimits.RequestBodyBytes;
            options.ValueLengthLimit = int.MaxValue;
        });

        services.Configure<KestrelServerOptions>(options =>
        {
            options.Limits.MaxRequestBodySize = BlobUploadLimits.RequestBodyBytes;
        });

        services.AddSingleton<IBlobImageStorage>(sp =>
        {
            var provider = (Environment.GetEnvironmentVariable("BLOB_PROVIDER") ?? "azure")
                .Trim()
                .ToLowerInvariant();

            return provider switch
            {
                "r2" => S3CompatibleBlobImageStorage.ForR2(),
                "minio" or "s3" => S3CompatibleBlobImageStorage.ForMinioOrS3(),
                "local" => new LocalFileBlobImageStorage(sp.GetRequiredService<IWebHostEnvironment>()),
                _ => new AzureBlobImageStorage()
            };
        });

        return services;
    }
}
